<script setup lang="ts">
import {onMounted,ref} from 'vue';import {imageData,type RequestFn} from './media';import {date} from './lib';
const props=defineProps<{request:RequestFn}>();const items=ref<Record<string,any>[]>([]),busy=ref(false),error=ref(''),notice=ref('');
async function load(){items.value=(await props.request('admin/payment-methods')).map((x:any)=>({...x,image_data:'',clear_image:false}))}
async function file(e:Event,item:Record<string,any>){try{error.value='';const f=(e.target as HTMLInputElement).files?.[0];if(f){item.image_data=await imageData(f);item.clear_image=false}}catch(e){error.value=String(e)}}
async function save(item:Record<string,any>){busy.value=true;error.value='';notice.value='';try{await props.request('admin/payment-methods','PUT',{id:item.id,version:item.version,name:item.name,instructions:item.instructions,enabled:item.enabled,image_data:item.image_data,clear_image:item.clear_image});await load();notice.value='收款方式已保存，既有订单保留创建时的收款码快照。'}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
onMounted(()=>load().catch(e=>error.value=String(e)));
</script>
<template><div class="alert">个人静态收款码需要人工核款。用户提交截图不会自动变为已支付；请以支付宝或微信的实际到账流水为准。</div><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert">{{notice}}</div><div class="plan-grid"><section v-for="m in items" :key="m.id" class="panel"><h3>{{m.provider==='alipay'?'支付宝':'微信'}}个人收款码</h3><form @submit.prevent="save(m)"><label>显示名称<input v-model="m.name" required maxlength="60"></label><label>收款说明<textarea v-model="m.instructions" maxlength="2000" rows="3" placeholder="例如收款人核对提示、付款备注要求，不要填写登录密码"></textarea></label><img v-if="m.image_data||m.image_configured&&!m.clear_image" :src="m.image_data||'/portal/v1/admin/payment-methods/'+m.id+'/image?v='+m.version" class="payment-qr" alt="当前收款码"><p v-else class="empty">尚未上传收款码</p><label>上传 / 更换收款码<input type="file" accept="image/png,image/jpeg" @change="file($event,m)"><small>图片会在浏览器压缩至 1MB 以内。请保存前扫码核对收款人。</small></label><label class="multi"><input type="checkbox" v-model="m.clear_image" @change="m.clear_image&&(m.enabled=false,m.image_data='')">删除已保存的收款码</label><label class="multi"><input type="checkbox" v-model="m.enabled" :disabled="m.clear_image||!m.image_data&&!m.image_configured">启用此收款方式</label><button class="primary" :disabled="busy">保存此收款方式</button><small class="block-note">上次更新 {{date(m.updated_at)}}</small></form></section></div><section class="panel"><h3>支付宝在线支付（可选）</h3><p class="muted">如需签名回调自动核款，可在「站点与连接」启用官方通道；使用个人静态码不需要开通此通道。两种方式可以并存。</p></section></template>
